import unittest
from held_policy import deferred_reload_proof,script

class DeferredReloadTests(unittest.TestCase):
    def rows(self,stamp="2026-10-05 19:00:02.100",request="7",profile="/Users/owned/.config/keypath/keypath.kbd"):
        return ["[2026-10-05 19:00:00.500] Starting reload request_id=7 (port=37001)",
                "["+stamp+"] Received line: '{\"ConfigFileReload\":{\"new\":\""+profile+"\"}}'",
                "["+stamp+"] Reload(wait) ok (request_id="+request+") duration=1500ms epoch=3"]
    def test_matching_completion(self):
        deferred_reload_proof(self.rows(),dict(home="/Users/owned"),1791252002,lambda x:x)
    def test_early_completion_rejected(self):
        with self.assertRaises(RuntimeError):deferred_reload_proof(self.rows("2026-10-05 19:00:01.100"),dict(home="/Users/owned"),1791252002,lambda x:x)
    def test_mismatched_request_rejected(self):
        with self.assertRaises(RuntimeError):deferred_reload_proof(self.rows(request="8"),dict(home="/Users/owned"),1791252002,lambda x:x)
    def test_wrong_profile_rejected(self):
        with self.assertRaises(RuntimeError):deferred_reload_proof(self.rows(profile="/Users/other/profile"),dict(home="/Users/owned"),1791252002,lambda x:x)
    def test_short_hold(self):
        self.assertIn("2000000 0 0 0 0 0 0 0",script("11111111-1111-4111-8111-111111111111","reload-deferred"))

import test_held_policy
from unittest.mock import patch

class DeferredReleaseBoundaryTests(unittest.TestCase):
    def setUp(self):
        test_held_policy.HeldTransitionTests.setUp(self)
    def check(self):return test_held_policy.HeldTransitionTests.check(self)
    def deferred(self,t):
        self.result['action']='reload-deferred'
        self.trace[1].update(scheduledUs=3000000,submittedUs=3000002)
        self.result['controlOffEpoch']=t
        self.result['releaseProof']['observedAt']=t+.01
        for rows in ('flagsChangedJournal','combinedSessionControlJournal'):
            for row in self.result['releaseProof'][rows]+self.result['finalTarget'][rows]:
                if row.get('control') in (False,0):row['observedAt']=t
        self.result['reloadAckObservedAt']=t+.02
    def test_deferred_release_overlap_is_explicit(self):
        self.deferred(102.5)
        with patch('held_policy.deferred_reload_proof'):
            self.assertTrue(self.check()['exactOrderingUnresolved'])
    def test_deferred_release_too_early_rejected(self):
        self.deferred(102.3)
        with patch('held_policy.deferred_reload_proof'),self.assertRaises(RuntimeError):self.check()
    def test_deferred_release_too_late_rejected(self):
        self.deferred(104.6)
        with patch('held_policy.deferred_reload_proof'),self.assertRaises(RuntimeError):self.check()

