import copy,unittest,uuid,zlib,hashlib
from held_policy import accept,script
N='11111111-1111-4111-8111-111111111111'
NEW='22222222-2222-4222-8222-222222222222'
class HeldTransitionTests(unittest.TestCase):
 def setUp(self):
  self.b=dict(uid=502,home='/Users/qa',runNonce=N,owner=dict(parentPID=10,workerPID=11,nonce=N),target=dict(pid=12,nonce=NEW),device=dict(registryEntryID=42,vendorID=51966,productID=16400,serialNumber=None,locationID=123),guestMinusHostLower=0.,guestMinusHostUpper=.1)
  def row(t,on,combined=False):
   x=dict(sequence=1 if on else 2,observedAt=t,monotonicAt=t,active=True,windowKey=True,focusLost=False,focusedMode='normal',requestedResponderFocused=True,secureInputEnabled=0,mode='normal',control=on)
   if combined:x.update(source='CGEventSourceCombinedSessionState',flags=262144 if on else 0,localDowns=0,localUps=0,localHeld=[])
   else:x.update(keyCode=59,modifiers=262144 if on else 0,downs=0,ups=0,held=[],eventTimestamp=t-.1)
   return x
  self.on=row(100.7,True);self.up=row(102.,False);self.con=row(100.7,True,True);self.coff=row(102.05,False,True)
  def target(t,on):return dict(pid=12,uid=502,nonce=NEW,observedAt=t,monotonicAt=t,active=True,windowKey=True,focusLost=False,focusedMode='normal',requestedResponderFocused=True,secureTest=False,secureInputEnabled=0,text='',downs=0,ups=0,held=[],modifiers=262144 if on else 0,combinedSessionControl=on,flagsChangedDropped=0,keyEventsDropped=0,combinedSessionControlDropped=0,flagsChangedJournal=[self.on] if on else [self.on,self.up],combinedSessionControlJournal=[self.con] if on else [self.con,self.coff],keyEventsJournal=[])
  record=dict(device=self.b['device'],owner=dict(parentPID=10,workerPID=11,nonce=N,generation=N),original=[],applied=[dict(HIDKeyboardModifierMappingSrc=0x700000039,HIDKeyboardModifierMappingDst=0x70000006D)])
  def worker(pid,nonce,t,held):return dict(pid=pid,ownerPID=10,report=dict(pid=pid,uid=502,nonce=nonce,managedCapsGeneration=N if pid==11 else None,state='running',tapActive=True,heldOutputUsages=held,timestamp=t-978307200))
  hp=dict(parents=[dict(pid=10)],workers=[worker(11,N,100.99,[224])],target=target(101.,True))
  self.result=dict(postconditionsObserved=True,action='reload',owner=self.b['owner'],targetBinding=self.b['target'],armedEpoch=99.,triggerEpoch=101.,profileWriteCompletedAt=101.1,controlOffEpoch=102.,afterObservedAt=110.1,heldProof=hp,journalProof=record,mappingProof=dict(device=self.b['device'],mappings=record['applied']),releaseProof=target(102.1,False),finalTarget=target(110.,False),afterRuntime=dict(parents=[dict(pid=10)],workers=[worker(11,N,109.99,[])]),afterJournal=record,afterMapping=dict(device=self.b['device'],mappings=record['applied']),reloadAckObservedAt=102.2,reloadLogFindings=['Reload(wait) ok request_id=owned'],beforeProfileSHA256=hashlib.sha256(b'(defcfg)\n(defsrc caps q)\n(deflayer base (tap-hold 200 200 esc lctl) a)\n').hexdigest())
  run='capsheld-'+uuid.UUID(N).hex
  self.status=dict(runId=run,state='complete',reportsSubmitted=2)
  self.start=dict(requestHostEpoch=100.,replyHostEpoch=100.01,delayMs=500,runId=run)
  self.trace=[dict(sequence=1,modifiers=0,keys=[57,0,0,0,0,0],scheduledUs=1000000,submittedUs=1000001,latenessUs=1),dict(sequence=2,modifiers=0,keys=[0]*6,scheduledUs=9000000,submittedUs=9000002,latenessUs=2)]
 def check(self):return accept(self.result,self.trace,self.start,self.b,self.status)
 def test_reload(self):self.assertTrue(self.check()['passed'])
 def test_ordinary(self):
  r=self.result;r['action']='ordinary';r['afterJournal']=None;r['afterMapping']['mappings']=[]
  w=r['afterRuntime']['workers'][0];w['pid']=13;w['report'].update(pid=13,nonce='33333333-3333-4333-8333-333333333333',managedCapsGeneration=None)
  self.assertTrue(self.check()['passed'])
 def test_stale_identity(self):
  self.result['heldProof']['workers'][0]['report']['nonce']=NEW
  with self.assertRaises(RuntimeError):self.check()
 def test_stale_target(self):
  self.result['releaseProof']['nonce']=N
  with self.assertRaises(RuntimeError):self.check()
 def test_missing_physical_evidence(self):
  self.trace=[]
  with self.assertRaises(RuntimeError):self.check()
 def test_late_release(self):
  self.result['controlOffEpoch']=108.6
  with self.assertRaises(RuntimeError):self.check()
 def test_late_ack(self):
  self.result['reloadAckObservedAt']=108.6
  with self.assertRaises(RuntimeError):self.check()
 def test_combined_proof_missing(self):
  self.result['releaseProof']['combinedSessionControlJournal']=[self.con]
  with self.assertRaises(RuntimeError):self.check()
 def test_secure_input_not_off(self):
  self.result['releaseProof']['secureInputEnabled']=1
  with self.assertRaises(RuntimeError):self.check()
 def test_integer_two_rejected(self):
  self.result['releaseProof']['secureInputEnabled']=2
  with self.assertRaises(RuntimeError):self.check()
 def test_function_never_fullallup_claim(self):
  self.result['finalTarget']['modifiers']=8388608
  x=self.check();self.assertFalse(x['fullModifierAllUpClaim']);self.assertTrue(x['retainedFunctionFlag'])
 def test_key_event_mode_is_not_required(self):
  r=self.result;t=r['finalTarget'];t.update(downs=1,ups=1)
  t['keyEventsJournal']=[dict(sequence=i+1,keyCode=79,type=kind,modifiers=8388608,held=[79] if kind=='down' else [],active=True,windowKey=True,focusLost=False,focusedMode='normal',requestedResponderFocused=True,secureInputEnabled=0,observedAt=103.+i) for i,kind in enumerate(['down','up'])]
  self.assertTrue(self.check()['passed'])
 def test_reasserted_control_refused(self):
  r=copy.deepcopy(self.on);r.update(sequence=3,observedAt=103.,monotonicAt=103.,eventTimestamp=102.9)
  self.result['finalTarget']['flagsChangedJournal'].append(r)
  with self.assertRaises(RuntimeError):self.check()
 def test_fixed_script(self):
  s=script(N);head,*lines=s.splitlines();payload='\n'.join(lines)+'\n'
  self.assertEqual(lines,['0 0 57 0 0 0 0 0','8000000 0 0 0 0 0 0 0']);self.assertIn('2 1 9000000',head)
  self.assertEqual(int(head.split()[-1],16),zlib.crc32(payload.encode())&0xffffffff)
if __name__=='__main__':unittest.main()
